        *{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:88px}body{margin:0;color:var(--kl-ink);background:var(--kl-paper);font:400 16px/1.6 var(--font-sans,ui-sans-serif,system-ui,sans-serif)}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}button{cursor:pointer}svg{display:block;width:20px;height:20px;flex:none}.kl-utility{background:var(--kl-red-dark);color:#fff8e9;font-size:13px}.kl-utility-inner{display:flex;min-height:38px;align-items:center;justify-content:space-between;gap:20px}.kl-utility p{margin:0}.kl-header{position:sticky;top:0;z-index:30;border-bottom:1px solid var(--kl-line);background:rgb(245 241 231 / 96%);backdrop-filter:blur(14px)}.kl-header-inner{display:flex;min-height:78px;align-items:center;justify-content:space-between;gap:26px}.kl-brand{display:flex;align-items:center;gap:13px}.kl-brand-mark{display:grid;width:43px;height:43px;place-items:center;border:1px solid var(--kl-red);color:var(--kl-red);font:700 24px/1 var(--kl-serif)}.kl-brand-copy{display:grid;line-height:1.2}.kl-brand-copy strong{font-size:16px;letter-spacing:.04em;text-transform:uppercase}.kl-brand-copy small{margin-top:4px;color:var(--kl-muted);font-size:13px}.kl-nav{display:flex;align-items:center;gap:clamp(14px,2vw,26px);font-size:14px;font-weight:700}.kl-nav a{padding-block:9px}.kl-nav a:hover{color:var(--kl-red)}.kl-nav .kl-nav-cta{padding:10px 14px;border:1px solid var(--kl-red);color:var(--kl-red)}.kl-menu{display:none;width:44px;height:44px;place-items:center;border:1px solid var(--kl-line);background:transparent}.kl-menu svg{width:22px;height:22px}
        .kl-hero{padding-block:28px 0}.kl-hero-panel{position:relative;display:grid;min-height:610px;grid-template-columns:minmax(0,1.08fr) minmax(360px,.92fr);overflow:hidden;background:var(--kl-leaf);color:#fff}.kl-hero-photo{position:absolute;inset:0 0 0 40%;width:60%;height:100%;object-fit:cover;object-position:center}.kl-hero-panel:after{position:absolute;inset:0;content:"";background:linear-gradient(90deg,#27362feF 0%,#27362f 35%,rgb(39 54 47 / 83%) 48%,rgb(39 54 47 / 12%) 79%),linear-gradient(0deg,rgb(23 34 29 / 42%),transparent 45%)}.kl-hero-copy{position:relative;z-index:1;display:flex;max-width:690px;flex-direction:column;align-items:flex-start;justify-content:center;padding:clamp(35px,7vw,88px)}.kl-kicker{display:flex;align-items:center;gap:11px;color:var(--kl-yellow);font-size:13px;font-weight:850;letter-spacing:.16em;text-transform:uppercase}.kl-kicker:before{width:27px;height:1px;background:currentColor;content:""}.kl-hero h1{max-width:9ch;margin:22px 0 18px;font:700 clamp(66px,8.4vw,112px)/.86 var(--kl-serif);letter-spacing:-.075em}.kl-hero-copy>p{max-width:40ch;margin:0;color:#f0eee5;font-size:18px;line-height:1.65}.kl-hero-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:30px}.kl-button{display:inline-flex;min-height:49px;align-items:center;justify-content:center;gap:11px;padding:0 17px;border:1px solid var(--kl-yellow);color:var(--kl-ink);background:var(--kl-yellow);font-size:14px;font-weight:800;transition:transform .18s ease,background .18s ease}.kl-button:hover{transform:translateY(-2px);background:#f0d47e}.kl-button.secondary{border-color:rgb(255 255 255 / 52%);color:#fff;background:transparent}.kl-button svg{width:17px;height:17px}.kl-hero-caption{position:absolute;right:20px;bottom:18px;z-index:2;max-width:290px;padding:10px 13px;background:rgb(29 41 39 / 86%);font-size:12px}.kl-hero-caption strong,.kl-hero-caption span{display:block}.kl-hero-caption span{color:#f1ecdf}.kl-news-ribbon{display:grid;grid-template-columns:auto minmax(0,1f