        .kl-service-layout{display:grid;grid-template-columns:.82fr 1.18fr;gap:clamp(35px,8vw,100px)}.kl-service-intro h2{max-width:9ch;margin:10px 0 16px;font:700 clamp(42px,5vw,66px)/.93 var(--kl-serif);letter-spacing:-.06em}.kl-service-intro p{max-width:36ch;color:var(--kl-muted);font-size:16px}.kl-service-list{border-top:1px solid var(--kl-line)}.kl-service-item{display:grid;grid-template-columns:48px minmax(0,1fr);gap:13px;padding:18px 0;border-bottom:1px solid var(--kl-line)}.kl-service-no{color:var(--kl-red);font-size:13px;font-weight:900}.kl-service-item details{min-width:0}.kl-service-item summary{display:flex;align-items:center;justify-content:space-between;gap:18px;cursor:pointer;list-style:none;font-size:18px;font-weight:800}.kl-service-item summary::-webkit-details-marker{display:none}.kl-service-item summary svg{width:18px;height:18px;color:var(--kl-red);transition:transform .18s}.kl-service-item details[open] summary svg{transform:rotate(45deg)}.kl-service-item p{margin:10px 0 0;color:var(--kl-muted);font-size:15px}
