        .kl-index{display:grid;grid-template-columns:.72fr 1.28fr;gap:48px;align-items:start}.kl-index-intro h2{max-width:8ch;margin:10px 0;font:700 clamp(43px,5.4vw,69px)/.91 var(--kl-serif);letter-spacing:-.06em}.kl-index-intro>p{color:var(--kl-muted);font-size:16px}.kl-index-status{display:inline-flex;margin-top:12px;padding:7px 10px;border:1px solid var(--kl-line);font-size:13px;font-weight:800}.kl-dimensions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.kl-dimension{padding:18px;border:1px solid var(--kl-line);background:var(--kl-white)}.kl-dimension-head{display:flex;justify-content:space-between;gap:12px}.kl-dimension h3{margin:0;font-size:16px}.kl-dimension strong{font-size:14px}.kl-dimension p{margin:8px 0 0;color:var(--kl-muted);font-size:14px}.kl-index-note{grid-column:1/-1;color:var(--kl-muted);font-size:13px}
        .kl-project-head{display:flex;align-items:end;justify-content:space-between;gap:26px;margin-bottom:24px}.kl-project-head h2{margin:8px 0 0;font:700 clamp(42px,5.5vw,72px)/.9 var(--kl-serif);letter-spacing:-.06em}.kl-project-head>p{max-width:38ch;color:var(--kl-muted);font-size:16px}.kl-project-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;align-items:start}.kl-project-card{position:relative;min-width:0;padding:21px;border:1px solid var(--kl-line);border-top:4px solid var(--kl-leaf);background:var(--kl-white)}.kl-project-meta{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px;color:var(--kl-muted);font-size:13px}.kl-project-card h3{margin:19px 0 8px;font:700 24px/1.12 var(--kl-serif);letter-spacing:-.035em}.kl-project-card>p{min-height:50px;color:var(--kl-muted);font-size:15px}.kl-project-bottom{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:19px;padding-top:13px;border-top:1px solid var(--kl-line);font-size:14px}.kl-project-bottom span{color:var(--kl-muted)}.kl-project-detail{border:0;padding:7px 0;color:var(--kl-red-dark);background:transparent;font-weight:850;text-decoration:underline;text-underline-offset:3px}.kl-project-overlay{position:absolute;inset:8px;z-index:5;display:none;overflow:auto;padding:16px;border:1px solid var(--kl-line);background:var(--kl-white);box-shadow:0 14px 38px rgb(28 38 33 / 24%)}.kl-project-overlay.open{display:block}.kl-overlay-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-bottom:9px;border-bottom:1px solid var(--kl-line)}.kl-overlay-head strong{font-size:15px}.kl-overlay-close{display:grid;width:38px;height:38px;place-items:center;border:1px solid var(--kl-line);background:white}.kl-overlay-row{display:flex;justify-content:space-between;gap:14px;padding:9px 0;border-bottom:1px solid var(--kl-line);font-size:14px}.kl-overlay-row span{color:var(--kl-muted)}.kl-overlay-row strong{text-align:right}
        .kl-community{display:grid;grid-template-columns:1.05fr .95fr;gap:20px}.kl-community-main{display:flex;min-height:330px;flex-direction:column;justify-content:space-between;padding:30px;color:#fff;background:var(--kl-leaf)}.kl-community-main h2{max-width:10ch;margin:14px 0;font:700 clamp(39px,5vw,62px)/.92 var(--kl-serif);letter-spacing:-.06em}.kl-community-main p{max-width:44ch;color:#e9eee3;font-size:16px}.kl-community-aside{display:grid;align-content:center;gap:12px;padding:28px;border:1px solid var(--kl-line);background:var(--kl-white)}.kl-community-aside article{padding-bottom:13px;border-bottom:1px solid var(--kl-line)}.kl-community-aside article:last-child{padding-bottom:0;border-bottom:0}.kl-community-aside span{color:var(--kl-red);font-size:12px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}.kl-community-aside h3{margin:6px 0;font:700 23px/1.1 var(--kl-serif)}.kl-community-aside p{margin:0;color:var(--kl-muted);font-size:14px}
