        .kl-chat{position:fixed;right:22px;bottom:22px;z-index:49;width:min(390px,calc(100vw - 28px));display:none;flex-direction:column;overflow:hidden;border:1px solid var(--kl-line);background:var(--kl-white);box-shadow:0 18px 56px rgb(31 42 35 / 24%)}.kl-chat.open{display:flex}.kl-chat-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 17px;color:#fff;background:var(--kl-leaf)}.kl-chat-head strong{font-size:16px}.kl-chat-close{display:grid;width:40px;height:40px;place-items:center;border:1px solid rgb(255 255 255 / 50%);color:#fff;background:transparent}.kl-chat-body{display:flex;max-height:min(570px,calc(100dvh - 120px));flex-direction:column;overflow:auto;padding:14px;background:#f7f4ec}.kl-chat-messages{display:flex;flex-direction:column;gap:9px}.kl-chat-message{max-width:88%;align-self:flex-start;padding:10px 12px;border-radius:12px 12px 12px 2px;background:#e9e5d8;font-size:14px;white-space:pre-line}.kl-chat-message.is-user{align-self:flex-end;border-radius:12px 12px 2px 12px;color:white;background:var(--kl-leaf)}.kl-chat-controls{padding-top:12px}.kl-chat-prompt{margin-bottom:8px;color:var(--kl-muted);font-size:13px}.kl-chat-input{width:100%;min-height:46px;padding:10px 12px;border:1px solid var(--kl-line);background:white;font-size:15px}.kl-chat-input:focus{outline:2px solid var(--kl-leaf);outline-offset:1px}.kl-chat-input.textarea{min-height:90px}.kl-chat-options,.kl-chat-actions{display:flex;flex-wrap:wrap;gap:8px}.kl-chat-actions{justify-content:flex-end;padding-top:12px}.kl-chat-option,.kl-chat-actions button{min-height:42px;padding:0 13px;border:1px solid var(--kl-line);color:var(--kl-ink);background:white;font-size:14px;font-weight:800}.kl-chat-actions button.primary,.kl-chat-option:hover{border-color:var(--kl-leaf);color:white;background:var(--kl-leaf)}.kl-chat-error{min-height:20px;padding-top:5px;color:#9b3127;font-size:13px}.kl-chat-toggle{position:fixed;right:22px;bottom:22px;z-index:48;display:inline-flex;