    <section class="kl-chat" id="kl-chat-panel" aria-label="Form usulan warga" aria-hidden="true"><div class="kl-chat-head"><strong>Usulan warga</strong><button class="kl-chat-close" id="kl-chat-close" type="button" aria-label="Tutup percakapan"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="kl-chat-body"><div class="kl-chat-messages" id="kl-chat-messages" aria-live="polite"></div><div class="kl-chat-controls" id="kl-chat-controls"></div><div class="kl-chat-actions" id="kl-chat-actions"></div><p class="kl-chat-error" id="kl-chat-error" role="alert"></p></div></section>
    <script>
        const klSafe=(tag,className,text)=>{const element=document.createElement(tag);element.className=className;element.textContent=text??'';return element};
        const klMoney=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0);
        const klNav=document.querySelector('#kl-nav'),klMenu=document.querySelector('#kl-menu');klMenu.addEventListener('click',()=>{const open=klNav.classList.toggle('open');klMenu.setAttribute('aria-expanded',String(open));klMenu.setAttribute('aria-label',open?'Tutup menu':'Buka menu')});klNav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{klNav.classList.remove('open');klMenu.setAttribute('aria-expanded','false')}));
        const klProjectFields=[['Lokasi',project=>project.location],['Tahun',project=>project.year],['Status',project=>project.status],['Volume',project=>project.volume],['Sumber dana',project=>project.funding],['Pelaksana',project=>project.executor],['Jadwal',project=>project.schedule],['Progres',project=>`${project.progress??0}%`],['Realisasi',project=>klMoney(project.spent)]];
        function klRenderProjects(projects){const list=document.querySelector('#kl-project-grid');list.replaceChildren();projects.forEach(project=>{const card=document.createElement('article');card.className='kl-project-card';const meta=document.createElement('div');meta.className='kl-project-meta';meta.append(klSafe('span','',`Tahun ${project.year||'—'} · ${project.status||'Status belum tersedia'}`));const title=klSafe('h3','',project.title||'Nama pekerjaan');const summary=klSafe('p','',project.summary||project.location||'Rincian belum tersedia.');const bottom=document.createElement('div');bottom.className='kl-project-bottom';bottom.append(klSafe('span','',project.funding||'Anggaran belum tersedia'));const detail=klSafe('button','kl-project-detail','Rincian pekerjaan');detail.type='button';bottom.append(detail);card.append(meta,title,summary,bottom);const overlay=document.createElement('div');overlay.className='kl-project-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-label',`Rincian ${project.title||'pekerjaan'}`);const head=document.createElement('div');head.className='kl-overlay-head';head.append(klSafe('strong','','Rincian pekerjaan'));const close=klSafe('button','kl-overlay-close','');close.type='button';close.setAttribute('aria-label','Tutup rincian');close.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 6 12 12M18 6 6 18"/></svg>';close.addEventListener('click',()=>overlay.classList.remove('open'));head.append(close);overlay.append(head);klProjectFields.forEach(([label,get])=>{const value=get(project);if(value===undefined||value===null||value==='')return;const row=document.createElement('div');row.className='kl-overlay-row';row.append(klSafe('span','',label),klSafe('strong','',String(value)));overlay.append(row)});detail.addEventListener('click',()=>overlay.classList.add('open'));card.append(overlay);list.append(card)})}
        const klFallbackProjects=[{title:'Peningkatan jalan lingkungan',summary:'Perbaikan akses jalan di lingkungan permukiman warga.',year:2026,status:'Perencanaan',funding:'Rp 145.000.000',location:'Dusun I',volume:'160 meter',executor:'Tim pelaksana',schedule:'Juni–September 2026',progress:20,spent:29000000,sample:true},{title:'Perbaikan saluran air',summary:'Penataan saluran untuk mendukung lingkungan permukiman.',year:2026,status:'Berjalan',funding:'Rp 98.000.000',location:'Dusun II',volume:'85 meter',executor:'Tim pelaksana',schedule:'Mei–Agustus 2026',progress:55,spent:53900000,sample:true},{title:'Pengembangan fasilitas desa',summary:'Pengadaan sarana pendukung kegiatan dan pelayanan warga.',year:2026,status:'Selesai',funding:'Rp 62.000.000',location:'Kantor desa',volume:'1 paket',executor:'Pemerintah desa',schedule:'Januari–Maret 2026',progress:100,spent:62000000,sample:true}];fetch('/api/desa/klaseman/content').then(response=>response.ok?response.json():Promise.reject()).then(data=>klRenderProjects(data.projects?.length?data.projects:klFallbackProjects)).catch(()=>klRenderProjects(klFallbackProjects));
        const klYear=document.querySelector('#kl-budget-year'),klBudgetLines=document.querySelector('#kl-budget-lines'),klBudgetValues={2026:{revenue:2450000000,expenditure:2380000000,financing:70000000,realized:1620000000,villageFund:850000000},2025:{revenue:2210000000,expenditure:2150000000,financing:60000000,realized:1950000000,villageFund:780000000}};function klRenderBudget(budget,year){document.querySelector('#kl-budget-year-title').textContent=year;klBudgetLines.replaceChildren();[['Pendapatan',budget.revenue],['Belanja',budget.expenditure],['Pembiayaan',budget.financing],['Realisasi',budget.realized]].forEach(([label,value])=>{const row=document.createElement('div');row.className='kl-budget-line';row.append(klSafe('span','',label),klSafe('strong','',klMoney(value)));klBudgetLines.append(row)});document.querySelector('#kl-village-fund').textContent=klMoney(budget.villageFund);}klYear.addEventListener('change',()=>klRenderBudget(klBudgetValues[klYear.value],klYear.value));fetch('/api/desa/klaseman/budgets').then(response=>response.ok?response.json():Promise.reject()).then(budgets=>{if(!budgets.length)return;klBudgetValues.fromApi=budgets;budgets.forEach(item=>{const option=document.createElement('option');option.value=item.year;option.textContent=String(item.year);klYear.append(option)});klYear.value=String(budgets[0].year);klRenderBudget({...budgets[0],villageFund:budgets[0].villageFund||0,fromApi:true},budgets[0].year)}).catch(()=>klRenderBudget(klBudgetValues[klYear.value],klYear.value));
        const klQuestions=[{key:'title',prompt:'Apa usulan yang ingin disampaikan?',required:true,type:'text'},{key:'location',prompt:'Di mana usulan ini diperlukan?',required:true,type:'text'},{key:'category',prompt:'Pilih bidang usulan.',required:false,type:'choice',options:['Infrastruktur','Lingkungan','Sosial','Ekonomi','Lainnya']},{key:'description',prompt:'Jelaskan usulan secara singkat.',required:true,type:'textarea'},{key:'name',prompt:'Nama (opsional).',required:false,type:'text'},{key:'contact',prompt:'Nomor telepon (opsional).',required:false,type:'text'}];let klAnswers={},klStep=0;const klChat=document.querySelector('#kl-chat-panel'),klMessages=document.querySelector('#kl-chat-messages'),klControls=document.querySelector('#kl-chat-controls'),klActions=document.querySelector('#kl-chat-actions'),klError=document.querySelector('#kl-chat-error'),klToggle=document.querySelector('#kl-chat-toggle');function klSay(text,user=false){klMessages.append(klSafe('div',`kl-chat-message${user?' is-user':''}`,text));klMessages.parentElement.scrollTop=klMessages.parentElement.scrollHeight}function klAction(label,handler,primary=false){const button=klSafe('button',primary?'primary':'',label);button.type='button';button.addEventListener('click',handler);return button}function klCloseChat(reset=true){klChat.classList.remove('open');klChat.setAttribute('aria-hidden','true');klToggle.setAttribute('aria-expanded','false');if(reset){klAnswers={};klStep=0;klMessages.replaceChildren();klControls.replaceChildren();klActions.replaceChildren();klError.textContent=''}}function klRenderQuestion(){klControls.replaceChildren();klActions.replaceChildren();klError.textContent='';if(klStep>=klQuestions.length){klSay('Periksa kembali usulan sebelum dikirim.');klSay(`${klAnswers.title}\n${klAnswers.location}\n${klAnswers.description}`);klActions.append(klAction('Batal',()=>klCloseChat()),klAction('Kirim usulan',klSubmitProposal,true));return}const question=klQuestions[klStep];klSay(question.prompt);klControls.append(klSafe('div','kl-chat-prompt',`${klStep+1} dari ${klQuestions.length}`));if(question.type==='choice'){const options=document.createElement('div');options.className='kl-chat-options';question.options.forEach(option=>options.append(klAction(option,()=>{klAnswers[question.key]=option;klSay(option,true);klStep++;klRenderQuestion()})));klControls.append(options)}else{const input=document.createElement(question.type==='textarea'?'textarea':'input');input.className='kl-chat-input';input.placeholder=question.key==='title'?'Judul usulan':question.key==='location'?'Lokasi':question.key==='description'?'Uraian singkat':question.key==='name'?'Nama':'Nomor telepon';input.setAttribute('aria-label',input.placeholder);input.maxLength=question.key==='description'?3000:160;if(question.type==='textarea')input.rows=3;klControls.append(input)}klActions.append(klAction('Batal',()=>klCloseChat()));if(!question.required)klActions.append(klAction('Lewati',()=>{klAnswers[question.key]='';klStep++;klRenderQuestion()}));klActions.append(klAction(klStep===klQuestions.length-1?'Tinjau':'Lanjut',()=>{const input=klControls.querySelector('input,textarea'),value=input?.value.trim()||'';if(question.required&&!value){klError.textContent='Bagian ini perlu diisi.';return}klAnswers[question.key]=value;if(value)klSay(value,true);klStep++;klRenderQuestion()},true))}async function klSubmitProposal(){klError.textContent='';const send=klActions.querySelector('.primary');send.disabled=true;try{const response=await fetch('/api/desa/klaseman/proposals',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({...klAnswers,website:''})});const result=response.status===204?{}:await response.json();if(!response.ok)throw new Error(result.message||'Usulan belum berhasil dikirim.');klMessages.replaceChildren();klControls.replaceChildren();klActions.replaceChildren();klSay(result.message||'Usulan berhasil dikirim.');klActions.append(klAction('Selesai',()=>klCloseChat(),true))}catch(exception){klError.textContent=exception.message;send.disabled=false}}klToggle.addEventListener('click',()=>{klChat.classList.add('open');klChat.setAttribute('aria-hidden','false');klToggle.setAttribute('aria-expanded','true');if(!klMessages.childElementCount)klRenderQuestion()});document.querySelector('#kl-chat-close').addEventListener('click',()=>klCloseChat(false));
    </script>
    @include('desa.partials.responsive')
</body>
</html>
